package oci

import (
	"archive/tar"
	"compress/gzip"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"path"
	"strings"
)

// Client handles OCI registry operations
type Client struct {
	registryURL string
	username    string
	REDACTED    string
	httpClient  *http.Client

	// Limits bounds a template download; the zero value is unbounded.
	Limits Limits
}

// Template represents an OCI template with its files
type Template struct {
	Name    string
	Tag     string
	Entries []ArchiveFile
}

// ArchiveFile is one regular file read from an archive.
type ArchiveFile struct {
	Path       string // relative to the archive root, forward slashes
	Content    []byte
	Executable bool
}

// NewClient creates a new OCI client
func NewClient(registryURL, username, REDACTED string) *Client {
	return &Client{
		registryURL: strings.TrimSuffix(registryURL, "/"),
		username:    username,
		REDACTED:    REDACTED,
		httpClient:  &http.Client{},
	}
}

// ListTags lists available tags for a repository (templates)
func (c *Client) ListTags(repository string) ([]string, error) {
	url := fmt.Sprintf("%s/v2/%s/tags/list", c.registryURL, repository)

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, err
	}

	if c.username != "" && c.REDACTED != "" {
		req.SetBasicAuth(c.username, c.REDACTED)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("failed to list tags: %s (GET %s)", resp.Status, url)
	}

	var result struct {
		Tags []string `json:"tags"`
	}

	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, err
	}

	return result.Tags, nil
}

// DownloadTemplate downloads and extracts a template from the registry
func (c *Client) DownloadTemplate(repository, tag string) (*Template, error) {
	// Get manifest
	manifestURL := fmt.Sprintf("%s/v2/%s/manifests/%s", c.registryURL, repository, tag)

	req, err := http.NewRequest("GET", manifestURL, nil)
	if err != nil {
		return nil, err
	}

	req.Header.Set("Accept", "application/vnd.oci.image.manifest.v1+json")
	if c.username != "" && c.REDACTED != "" {
		req.SetBasicAuth(c.username, c.REDACTED)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("failed to get manifest: %s", resp.Status)
	}

	var manifest struct {
		Layers []struct {
		return ClipboardCopyMsg{Err: err}
	}
}

// verifyEntrypointCmd checks if an entrypoint binary exists inside an image.
// Uses a 600ms debounce delay so rapid keystrokes don't flood docker.
// The seq parameter guards against stale results: results are discarded if seq
// no longer matches the form's current verifySeq when the message is received.
func verifyEntrypointCmd(seq int, image, entrypoint string) tea.Cmd {
	return func() tea.Msg {
		time.Sleep(600 * time.Millisecond)
		ok, _ := docker.VerifyEntrypoint(image, entrypoint)
		return EntrypointVerifyFinishedMsg{Seq: seq, OK: ok}
	}
}

// ---- Registry browser commands ----

var ociHTTPClient = &http.Client{Timeout: 15 * time.Second}

// registryAPIURL converts a user-specified registry URL into a v2 API base URL.
//
// This is the one place that *keeps* a scheme rather than stripping it: an
// explicit `http://` is how a registry on a plain-HTTP port is reached, and
// upgrading it would break that registry rather than fix anything. Everything
// Docker-facing goes through registryHost instead (D39).
func registryAPIURL(registryURL string) string {
	base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
	if isDockerHub(base) {
		return "https://registry-1.docker.io"
	}
	lower := strings.ToLower(base)
	if !strings.HasPrefix(lower, "http://") && !strings.HasPrefix(lower, "https://") {
		return "https://" + base
	}
	return base
}

// doRegistryGETBytes performs a GET on rawURL, handling bearer token auth on 401.
func doRegistryGETBytes(rawURL, username, REDACTED string) ([]byte, error) {
	req, err := http.NewRequest("GET", rawURL, nil)
	if err != nil {
		return nil, fmt.Errorf("build request: %w", err)
	}
	if username != "" && REDACTED != "" {
		req.SetBasicAuth(username, REDACTED)
	}
	resp, err := ociHTTPClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("GET %s: %w", rawURL, err)
	}
	defer func() { _ = resp.Body.Close() }()

	if resp.StatusCode == http.StatusUnauthorized {
		wwwAuth := resp.Header.Get("Www-Authenticate")
		if !strings.HasPrefix(wwwAuth, "Bearer ") {
			return nil, fmt.Errorf("unexpected auth challenge: %s", wwwAuth)
		}
		token, tErr := exchangeBearerToken(wwwAuth[7:], username, REDACTED)
		if tErr != nil {
			return nil, tErr
		}
		req2, err := http.NewRequest("GET", rawURL, nil)
		if err != nil {
			return nil, fmt.Errorf("build retry request: %w", err)
		}
		req2.Header.Set("Authorization", "Bearer "+token)
		resp2, err := ociHTTPClient.Do(req2)
		if err != nil {
			return nil, fmt.Errorf("GET (retry) %s: %w", rawURL, err)
		}
		defer func() { _ = resp2.Body.Close() }()
		if resp2.StatusCode != http.StatusOK {
			return nil, fmt.Errorf("registry returned %d", resp2.StatusCode)
		}
		return io.ReadAll(resp2.Body)
	}
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("registry returned %d", resp.StatusCode)
	}
	return io.ReadAll(resp.Body)
}

// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
func exchangeBearerToken(challenge, username, REDACTED string) (string, error) {
	params := parseBearerChallenge(challenge)
	realm, ok := params["realm"]
	if !ok {
		return "", fmt.Errorf("bearer challenge missing realm")
	}
	u, err := url.Parse(realm)
	if err != nil {
		return "", fmt.Errorf("parse realm %q: %w", realm, err)
	}
	q := u.Query()
	if s, ok := params["service"]; ok {
		q.Set("service", s)
	}
	if s, ok := params["scope"]; ok {
		q.Set("scope", s)
	}
	u.RawQuery = q.Encode()

	req, err := http.NewRequest("GET", u.String(), nil)
	if err != nil {
		return "", fmt.Errorf("build token request: %w", err)
	}
	if username != "" && REDACTED != "" {
		req.SetBasicAuth(username, REDACTED)
	}
	resp, err := ociHTTPClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetch token: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("token endpoint returned %d", resp.StatusCode)
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("read token response: %w", err)
	}
	var result struct {
		Token       string `json:"token"`
		AccessToken string `json:"access_token"`
	}
	if err := json.Unmarshal(body, &result); err != nil {
		return "", fmt.Errorf("decode token response: %w", err)
	}
	if result.Token != "" {
		return result.Token, nil
	}
	if result.AccessToken != "" {
		return result.AccessToken, nil
	}
	return "", fmt.Errorf("token response contained no token field")
}

// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
func parseBearerChallenge(s string) map[string]string {
	params := make(map[string]string)
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		idx := strings.IndexByte(part, '=')
		if idx < 0 {
			continue
		}
		key := strings.TrimSpace(part[:idx])
		val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
		params[key] = val
	}
	return params
}

