		m.findingToIgnore = nil
		return m, nil

	case sharedcomponents.OptionConfirmModalYesMsg:
		m.scanAllModal = nil
		return m.rescanAll(msg.Option)

	case sharedcomponents.OptionConfirmModalNoMsg:
		m.scanAllModal = nil
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		// Widths and height in one call; SetHeight accounts for the header row
		// internally, so m.height goes through as it is. Rows no longer depend
		// on the width — bubbles truncates each cell to its own column — so
		// there is nothing to rebuild here.
		m.resizeFindings()
		m.inventory.Resize(m.width, max(m.height, 5))
		// Update details viewport size and refresh content
		m.detailsViewport.Width = msg.Width
		m.detailsViewport.Height = msg.Height
		if m.state == StateDetails {
			m.detailsViewport.SetContent(m.buildDetailsContent())
		}
		return m, nil

	case tea.KeyMsg:
		// Whichever modal is open takes every key before the view sees one.
		if m.confirmModal != nil {
			var cmd tea.Cmd
			m.confirmModal, cmd = m.confirmModal.Update(msg)
			return m, cmd
		}
		if m.scanAllModal != nil {
			var cmd tea.Cmd
			m.scanAllModal, cmd = m.scanAllModal.Update(msg)
			return m, cmd
		}
		return m.handleKeyMsg(msg)

	case SecretIgnoredMsg:
		if msg.Error != nil {
			log.Printf("ERROR [security] ignore secret %s: %v", msg.Finding.File, msg.Error)
			return m, m.footer.Error("Failed to ignore secret — check logs")
		}
		return m, m.footer.Info(fmt.Sprintf("Added %s to .gitleaksignore", msg.Finding.File))

	case InventoryLoadedMsg:
		return m.handleInventoryLoaded(msg)

	case InventoryResultLoadedMsg:
		return m.handleInventoryResultLoaded(msg)

	case InventoryScanFinishedMsg:
		return m.handleInventoryScanFinished(msg)

	case InventoryScanStartingMsg:
		// The row is already spinning: the router recorded the transition
		// before handing the message on, and the snapshot rebuilt the rows.
		return m, nil

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleSpinnerTick advances the spinner while the caches are being read.
//
// It animates a *load* and nothing else now. A scan's frame comes from the
// registry, which holds the one chain for the whole application (D5), and the
// rows are restamped when its snapshot arrives — see handleJobsChanged.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.spinnerAlive() {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	m.spinnerFrameIdx++
	// The footer renders the frame, not a raw one: the spinner already carries
	// theme.SpinnerStyle() and restyling it would nest one sequence in another
	// (Rule 128).
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handleKeyMsg processes keyboard input
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch m.state {
	case StateInventory:
		return m.handleInventoryState(msg)
	case StateResults:
		return m.handleResultsState(msg)
	case StateDetails:
		return m.handleDetailsState(msg)
	}
	return m, nil
}
package security

import (
	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/scan"
)

// What went with the form (phase 3):
//
//   - ScanCompleteMsg, ScanProgressMsg and StartScanMsg drove the in-place
//     scanning screen. The inventory rescans in the background instead and
//     reports through InventoryScanFinishedMsg, so nothing waits on a whole
//     screen for one target.
//   - DepsCheckedMsg fed the Start button, the only thing left that read whether
//     a scanner was installed. The dashboard already reports that from
//     shared.State.Tools.
//   - SelectionRequestMsg / SelectionResultMsg / SelectionCancelledMsg were the
//     browser bridge: the form borrowed the workspaces or the images view to
//     pick a target. A target is a row of the inventory now.

// SecretIgnoredMsg is sent when a secret is added to .gitleaksignore
type SecretIgnoredMsg struct {
	Finding scan.Finding
	Error   error
}

// BackToOriginMsg is sent when the user presses Esc in StateResults to return to the originating view.
type BackToOriginMsg struct {
	Origin command.ViewType
}
package security

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
)

// What is being rescanned is the registry's answer, not this view's (§3.58).
//
// `scanTarget.Scanning` was a flag this view set and cleared itself, and
// `handleInventoryLoaded` had to carry it across every reload by hand: the
// caches say nothing about a scan that has not finished writing to them, so a
// refresh landing mid-rescan cleared the spinner and left the row looking
// settled. Reading the snapshot removes the reconciliation rather than fixing
// it — there is nothing to carry across a reload when the state was never here.
//
// It also makes the marker true for a scan started **elsewhere**. The inventory
// lists what `ws` and the images tab scan; a rescan launched from either of them
// is the same work on the same cache entry, and this view had no way to know.

// handleJobsChanged takes the router's snapshot and redecorates the rows.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.jobFrame = msg.Frame
	m.setInventory(m.inventory.Items())
	return m, nil
}

// scanRun builds the run behind ctrl+s and A. The label names the screen it was
// launched from, which is what `:jobs` shows.
func (m Model) scanRun(names []string) jobs.Run {
	return jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "inventory", names...)
}

// scanningTarget reports whether a target is queued or being scanned, whoever
// started it.
func (m Model) scanningTarget(name string) bool {
	return m.scanningTargets()[name]
}

// scanningTargets is every target with a scan in flight, from any view.
func (m Model) scanningTargets() map[string]bool {
	out := make(map[string]bool)
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if !item.State.Terminal() {
				out[item.Target] = true
			}
		}
	}
	return out
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────

func (m InventoryScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m InventoryScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.Name, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

// D10: rescanCmd had no starting message at all — only a finished one — so its
// items would have jumped straight from queued to done and the distinction
// between the two would have been decorative here.
var (
	_ jobs.Reporter = InventoryScanStartingMsg{}
	_ jobs.Reporter = InventoryScanFinishedMsg{}
)

