func TestTheLastFinishedScanSaysSo(t *testing.T) {
	m := onRemediation(t, baseEntries()[:1], map[string]cache.RemediationEntry{
		"golang:1.21": scannedAt(1, 1), "golang:1.23": scannedAt(1, 1),
