	m := onRemediation(t, baseEntries()[:1], nil)
	m = feed(t, m, RemediationScanFinishedMsg{Target: "/elsewhere", Ref: "golang:1.23", Entry: scannedAt(9, 9)})
	if _, ok := m.remediation.results["golang:1.23"]; ok {
